// The word "Carousel" the boot shows, in the brand's title face (Chillax):
// one line for landscape, in one bit (Semibold, lit or off), two for portrait,
// anti-aliased (Medium). The bitmaps are generated by tools/brand/wordmark.mjs
// into wordmark_data.cpp. Hardware-free: host-tested in test_wordmark.
#pragma once

#include <Adafruit_GFX.h>
#include <stdint.h>

// Levels 0 (off) to WORDMARK_LEVELS - 1 (full), 4 bits a pixel, two pixels a
// byte, the left one in the high nibble, each row padded to a byte
static const uint8_t WORDMARK_LEVELS = 16;

struct Wordmark {
  const uint8_t *levels;
  uint8_t w, h;
};

extern const Wordmark WORDMARK_WIDE, WORDMARK_TALL;

uint8_t wordmarkLevel(const Wordmark &m, int16_t x, int16_t y);

// The bitmap the canvas takes: the one line where it fits, the two lines
// otherwise (portrait).
const Wordmark &bootWordFor(const Adafruit_GFX &g);

// The word centred at x, its top row at y; each pixel the palette's text role
// at its level times light (0-255). Off pixels are not written, so the word
// lies over whatever the canvas holds.
void drawBootWord(Adafruit_GFX &g, int16_t x, int16_t y, uint8_t light);
